const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();

    useEffect(() => {
        if (!view) return;
        const ctrl = controls as unknown as OrbitControlsImpl;
        if (!ctrl) return;
        const currentTarget = ctrl.target.clone();
        const dist = camera.position.distanceTo(currentTarget) || 10;
        const offset = 0.001; 
        switch (view) {
            case '上視圖': camera.position.set(currentTarget.x, currentTarget.y + dist, currentTarget.z + offset); break;
            case '下視圖': camera.position.set(currentTarget.x, currentTarget.y - dist, currentTarget.z + offset); break;
            case '前視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z + dist); break;
            case '後視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z - dist); break;
            case '右視圖': camera.position.set(currentTarget.x + dist, currentTarget.y, currentTarget.z); break;
            case '左視圖': camera.position.set(currentTarget.x - dist, currentTarget.y, currentTarget.z); break;
        }
        ctrl.update();
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number]; type?: SnapType }> = ({ text, position, type }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
  let bgColor = "bg-black/80";
  let ringColor = "border-white/20";
  let textColor = "text-white";

  // SketchUp Style Colors
  if (type === 'vertex') { bgColor = "bg-green-600"; ringColor = "border-green-400"; }
  else if (type === 'midpoint') { bgColor = "bg-cyan-500"; ringColor = "border-cyan-300"; textColor="text-black"; }
  else if (type === 'edge') { bgColor = "bg-red-600"; ringColor = "border-red-400"; }
  else if (type === 'face') { bgColor = "bg-blue-600"; ringColor = "border-blue-400"; }
  else if (type === 'align') { bgColor = "bg-purple-600"; ringColor = "border-purple-400"; }

  // Highlight dimensions
  if (text.includes('W:') || text.includes('L:') || text.includes('R:') || text.includes('距離:')) {
      bgColor = "bg-slate-800";
      ringColor = "border-slate-500";
      textColor = "text-yellow-400 font-mono";
  }

  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
      <div className={`${bgColor} ${textColor} text-xs px-2 py-1 rounded-sm whitespace-nowrap backdrop-blur-sm border ${ringColor} shadow-[0_2px_4px_rgba(0,0,0,0.3)] font-bold flex items-center gap-1 transition-all -translate-y-8`}>
        {text}
      </div>
    </Html>
  );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'none' || type === 'grid') return null;

    // SketchUp Colors
    const color = 
        type === 'vertex' ? '#22c55e' : // Green
        type === 'midpoint' ? '#06b6d4' : // Cyan
        type === 'edge' ? '#ef4444' : // Red
        type === 'face' ? '#3b82f6' : // Blue
        '#a855f7'; // Purple (Align)

    return (
        <group>
             {/* The Point Indicator */}
             <group position={position}>
                {/* Vertex: Solid Green Circle */}
                {type === 'vertex' && (
                     <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <circleGeometry args={[0.08, 16]} />
                        <meshBasicMaterial color={color} depthTest={false} />
                    </mesh>
                )}
                {/* Midpoint: Solid Cyan Circle (SketchUp uses Cyan Dot) */}
                {type === 'midpoint' && (
                     <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <circleGeometry args={[0.08, 16]} />
                        <meshBasicMaterial color={color} depthTest={false} />
                    </mesh>
                )}
                {/* Edge: Red Square */}
                {type === 'edge' && (
                     <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <planeGeometry args={[0.12, 0.12]} />
                        <meshBasicMaterial color={color} depthTest={false} />
                    </mesh>
                )}
                {/* Face: Blue Diamond */}
                {type === 'face' && (
                     <mesh rotation={[-Math.PI/2, 0, Math.PI/4]}>
                        <planeGeometry args={[0.1, 0.1]} />
                        <meshBasicMaterial color={color} depthTest={false} />
                    </mesh>
                )}
                {/* Align: Purple Ring */}
                {type === 'align' && (
                    <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <ringGeometry args={[0.06, 0.1, 16]} />
                        <meshBasicMaterial color={color} depthTest={false} />
                    </mesh>
                )}

                {/* Outer Ring for visibility contrast */}
                {type !== 'align' && (
                    <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <ringGeometry args={[0.12, 0.14, 32]} />
                        <meshBasicMaterial color="white" transparent opacity={0.5} depthTest={false} />
                    </mesh>
                )}
            </group>

            {/* Edge Highlighting: If we are snapping to an edge/midpoint, draw the FULL edge */}
            {snapEdge && (type === 'edge' || type === 'midpoint') && (
                <Line 
                    points={[snapEdge[0], snapEdge[1]]}
                    color={color}
                    lineWidth={3}
                    depthTest={false}
                    transparent
                    opacity={0.8}
                />
            )}
        </group>
    );
}

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z);
      for (let i = 1; i < points.length; i++) {
        if (points[i]) s.lineTo(points[i].x, -points[i].z);
      }
    }
    s.closePath();
    return s;
  }, [points]);
  if (!shape) return null;
  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

// --- Multi-Selection Gizmo with Magnetic Snap ---
const SelectionGizmo: React.FC = () => {
    const { selectedIds, shapes, updateShapes, tool } = useApp();
    const { scene } = useThree();
    const proxyRef = useRef<THREE.Group>(null);
    const draggingRef = useRef<{ 
        startPos: THREE.Vector3; 
        initialShapePositions: Map<string, THREE.Vector3>;
        // Pre-calculated relative points for all selected objects
        movingPoints: { shapeId: string, rel: THREE.Vector3 }[];
        // Pre-calculated absolute points for all unselected objects
        staticPoints: THREE.Vector3[];
    } | null>(null);

    const [snapGuides, setSnapGuides] = useState<THREE.Vector3[][]>([]);

    // Calculate center of selection
    const selectionCenter = useMemo(() => {
        if (selectedIds.length === 0) return null;
        const selectedShapes = shapes.filter(s => selectedIds.includes(s.id));
        if (selectedShapes.length === 0) return null;

        let sumX = 0, sumY = 0, sumZ = 0;
        selectedShapes.forEach(s => {
            sumX += s.position[0];
            sumY += s.position[1];
            sumZ += s.position[2];
        });
        return new THREE.Vector3(sumX / selectedShapes.length, sumY / selectedShapes.length, sumZ / selectedShapes.length);
    }, [selectedIds, shapes]);

    const selectedShape = useMemo(() => 
        selectedIds.length === 1 ? shapes.find(s => s.id === selectedIds[0]) : null
    , [selectedIds, shapes]);

    useEffect(() => {
        if (proxyRef.current && selectionCenter && !draggingRef.current) {
            proxyRef.current.position.copy(selectionCenter);
            if (selectedShape) {
                // Align rotation for single object
                proxyRef.current.rotation.set(0, selectedShape.rotation, 0);
            } else {
                // Default to world alignment for multiple objects
                proxyRef.current.rotation.set(0, 0, 0);
            }
            proxyRef.current.scale.set(1, 1, 1);
        }
    }, [selectionCenter, selectedShape]);

    const handleDragStart = () => {
        if (!selectionCenter) return;
        const map = new Map<string, THREE.Vector3>();
        const movingPoints: { shapeId: string, rel: THREE.Vector3 }[] = [];
        const staticPoints: THREE.Vector3[] = [];

        // 1. Snapshot Moving Objects
        shapes.forEach(s => {
            if (selectedIds.includes(s.id)) {
                map.set(s.id, new THREE.Vector3(s.position[0], s.position[1], s.position[2]));
                // Save corner relative positions (to the selection center)
                s.points.forEach(p => {
                     const worldP = transformPoint(p, s);
                     movingPoints.push({
                         shapeId: s.id,
                         rel: worldP.clone().sub(selectionCenter)
                     });
                });
            } else {
                // 2. Snapshot Static Objects (Vertices)
                 s.points.forEach(p => {
                     staticPoints.push(transformPoint(p, s));
                });
            }
        });

        draggingRef.current = {
            startPos: selectionCenter.clone(),
            initialShapePositions: map,
            movingPoints,
            staticPoints
        };
        setSnapGuides([]);
    };

    const handleDrag = () => {
        if (!draggingRef.current || !proxyRef.current) return;

        const currentGizmoPos = proxyRef.current.position.clone();

        // --- Magnetic Snap Logic ---
        const { movingPoints, staticPoints, startPos } = draggingRef.current;

        // Raw Delta from start (Mouse intention)
        const rawDelta = currentGizmoPos.clone().sub(startPos);

        let snapAdjustmentX = 0;
        let snapAdjustmentZ = 0;
        let minDiffX = ALIGN_THRESHOLD;
        let minDiffZ = ALIGN_THRESHOLD;
        let bestGuideX: THREE.Vector3[] | null = null;
        let bestGuideZ: THREE.Vector3[] | null = null;

        if (movingPoints.length > 0 && staticPoints.length > 0) {
            // Check X alignment
            for (const mp of movingPoints) {
                // Where this point would be without snap
                const candidateX = startPos.x + mp.rel.x + rawDelta.x;

                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateX - sp.x);
                     if (diff < minDiffX) {
                         minDiffX = diff;
                         snapAdjustmentX = sp.x - candidateX; // Adjustment needed to align
                         // Create visual line
                         bestGuideX = [
                             new THREE.Vector3(sp.x, 0.5, -100),
                             new THREE.Vector3(sp.x, 0.5, 100)
                         ];
                     }
                }
            }
            // Check Z alignment
            for (const mp of movingPoints) {
                const candidateZ = startPos.z + mp.rel.z + rawDelta.z;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateZ - sp.z);
                     if (diff < minDiffZ) {
                         minDiffZ = diff;
                         snapAdjustmentZ = sp.z - candidateZ;
                         bestGuideZ = [
                             new THREE.Vector3(-100, 0.5, sp.z),
                             new THREE.Vector3(100, 0.5, sp.z)
                         ];
                     }
                }
            }
        }

        // Apply Movement to Objects with Snap Adjustment
        const finalDelta = new THREE.Vector3(
            rawDelta.x + snapAdjustmentX,
            rawDelta.y,
            rawDelta.z + snapAdjustmentZ
        );

        // Update Guides
        const newGuides = [];
        if (bestGuideX && Math.abs(snapAdjustmentX) > 0.0001) newGuides.push(bestGuideX);
        if (bestGuideZ && Math.abs(snapAdjustmentZ) > 0.0001) newGuides.push(bestGuideZ);
        setSnapGuides(newGuides);

        // Direct DOM update
        scene.children.forEach(child => {
            if (child.userData?.isShape && selectedIds.includes(child.userData.id)) {
                 const initial = draggingRef.current?.initialShapePositions.get(child.userData.id);
                 if (initial) {
                     child.position.set(
                         initial.x + finalDelta.x,
                         initial.y + finalDelta.y,
                         initial.z + finalDelta.z
                     );
                 }
            }
        });
    };

    const handleDragEnd = () => {
        if (!draggingRef.current || !proxyRef.current) return;
        const currentGizmoPos = proxyRef.current.position;

        const { movingPoints, staticPoints, startPos } = draggingRef.current;
        const rawDelta = currentGizmoPos.clone().sub(startPos);

        let snapAdjustmentX = 0;
        let snapAdjustmentZ = 0;
        let minDiffX = ALIGN_THRESHOLD;
        let minDiffZ = ALIGN_THRESHOLD;

        if (movingPoints.length > 0 && staticPoints.length > 0) {
            for (const mp of movingPoints) {
                const candidateX = startPos.x + mp.rel.x + rawDelta.x;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateX - sp.x);
                     if (diff < minDiffX) {
                         minDiffX = diff;
                         snapAdjustmentX = sp.x - candidateX;
                     }
                }
            }
            for (const mp of movingPoints) {
                const candidateZ = startPos.z + mp.rel.z + rawDelta.z;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateZ - sp.z);
                     if (diff < minDiffZ) {
                         minDiffZ = diff;
                         snapAdjustmentZ = sp.z - candidateZ;
                     }
                }
            }
        }

        const finalDelta = new THREE.Vector3(
            rawDelta.x + snapAdjustmentX,
            rawDelta.y,
            rawDelta.z + snapAdjustmentZ
        );

        const updates = selectedIds.map(id => {
            const initial = draggingRef.current?.initialShapePositions.get(id);
            if (!initial) return null;
            return {
                id,
                changes: {
                    position: [initial.x + finalDelta.x, initial.y + finalDelta.y, initial.z + finalDelta.z] as [number, number, number]
                }
            };
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];

        if (updates.length > 0) {
            updateShapes(updates);
        }
        draggingRef.current = null;
        setSnapGuides([]);
    };

    if (!selectionCenter || tool !== ToolType.SELECT) return null;

    return (
        <>
            <group ref={proxyRef} />
            <TransformControls
                // Key forces re-mount when selection changes to avoid "detached" gizmo issues
                key={selectedIds.join('-')}
                object={proxyRef}
                mode="translate"
                space={selectedShape ? "local" : "world"}
                onMouseDown={handleDragStart}
                onObjectChange={handleDrag}
                onMouseUp={handleDragEnd}
                translationSnap={0.01}
                size={0.8}
            />
            {/* Render Snap Alignment Guides */}
            {snapGuides.map((pts, i) => (
                <Line 
                    key={`snap-guide-${i}`} 
                    points={pts} 
                    color="#d946ef" // Fuchsia-500
                    lineWidth={2} 
                    dashed 
                    dashScale={10} 
                    depthTest={false}
                    opacity={0.8}
                    transparent
                />
            ))}
        </>
    );
};

