// ... (Keep CameraHandler, CursorTooltip, SnapIndicator, PreviewFill, SelectionGizmo unchanged from previous) ...
const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        const ctrl = controls as unknown as OrbitControlsImpl;
        if (!ctrl) return;
        const currentTarget = ctrl.target.clone();
        const dist = camera.position.distanceTo(currentTarget) || 10;
        const offset = 0.001; 
        switch (view) {
            case '上視圖': camera.position.set(currentTarget.x, currentTarget.y + dist, currentTarget.z + offset); break;
            case '下視圖': camera.position.set(currentTarget.x, currentTarget.y - dist, currentTarget.z + offset); break;
            case '前視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z + dist); break;
            case '後視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z - dist); break;
            case '右視圖': camera.position.set(currentTarget.x + dist, currentTarget.y, currentTarget.z); break;
            case '左視圖': camera.position.set(currentTarget.x - dist, currentTarget.y, currentTarget.z); break;
        }
        ctrl.update();
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number]; type?: SnapType }> = ({ text, position, type }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
  let bgColor = "bg-black/80";
  let ringColor = "border-white/20";
  let textColor = "text-white";
  if (type === 'vertex') { bgColor = "bg-green-600"; ringColor = "border-green-400"; }
  else if (type === 'midpoint') { bgColor = "bg-cyan-500"; ringColor = "border-cyan-300"; textColor="text-black"; }
  else if (type === 'edge') { bgColor = "bg-red-600"; ringColor = "border-red-400"; }
  else if (type === 'face') { bgColor = "bg-blue-600"; ringColor = "border-blue-400"; }
  else if (type === 'align') { bgColor = "bg-purple-600"; ringColor = "border-purple-400"; }
  if (text.includes('W:') || text.includes('L:') || text.includes('R:') || text.includes('距離:')) {
      bgColor = "bg-slate-800";
      ringColor = "border-slate-500";
      textColor = "text-yellow-400 font-mono";
  }
  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
      <div className={`${bgColor} ${textColor} text-xs px-2 py-1 rounded-sm whitespace-nowrap backdrop-blur-sm border ${ringColor} shadow-[0_2px_4px_rgba(0,0,0,0.3)] font-bold flex items-center gap-1 transition-all -translate-y-8`}>
        {text}
      </div>
    </Html>
  );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'none' || type === 'grid') return null;
    const color = type === 'vertex' ? '#22c55e' : type === 'midpoint' ? '#06b6d4' : type === 'edge' ? '#ef4444' : type === 'face' ? '#3b82f6' : '#a855f7';
    return (
        <group>
             <group position={position}>
                {type === 'vertex' && <mesh rotation={[-Math.PI/2, 0, 0]}><circleGeometry args={[0.08, 16]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'midpoint' && <mesh rotation={[-Math.PI/2, 0, 0]}><circleGeometry args={[0.08, 16]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'edge' && <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.12, 0.12]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'face' && <mesh rotation={[-Math.PI/2, 0, Math.PI/4]}><planeGeometry args={[0.1, 0.1]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'align' && <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[0.06, 0.1, 16]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type !== 'align' && <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[0.12, 0.14, 32]} /><meshBasicMaterial color="white" transparent opacity={0.5} depthTest={false} /></mesh>}
            </group>
            {snapEdge && (type === 'edge' || type === 'midpoint') && (
                <Line points={[snapEdge[0], snapEdge[1]]} color={color} lineWidth={3} depthTest={false} transparent opacity={0.8} />
            )}
        </group>
    );
}

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z);
      for (let i = 1; i < points.length; i++) {
        if (points[i]) s.lineTo(points[i].x, -points[i].z);
      }
    }
    s.closePath();
    return s;
  }, [points]);
  if (!shape) return null;
  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

const SelectionGizmo: React.FC = () => {
    // ... (Keep existing implementation of SelectionGizmo)
    const { selectedIds, shapes, updateShapes, tool } = useApp();
    const { scene } = useThree();
    const proxyRef = useRef<THREE.Group>(null);
    const draggingRef = useRef<{ 
        startPos: THREE.Vector3; 
        initialShapePositions: Map<string, THREE.Vector3>;
        movingPoints: { shapeId: string, rel: THREE.Vector3 }[];
        staticPoints: THREE.Vector3[];
    } | null>(null);
    const [snapGuides, setSnapGuides] = useState<THREE.Vector3[][]>([]);

    const selectionCenter = useMemo(() => {
        if (selectedIds.length === 0) return null;
        const selectedShapes = shapes.filter(s => selectedIds.includes(s.id));
        if (selectedShapes.length === 0) return null;
        let sumX = 0, sumY = 0, sumZ = 0;
        selectedShapes.forEach(s => { sumX += s.position[0]; sumY += s.position[1]; sumZ += s.position[2]; });
        return new THREE.Vector3(sumX / selectedShapes.length, sumY / selectedShapes.length, sumZ / selectedShapes.length);
    }, [selectedIds, shapes]);

    const selectedShape = useMemo(() => selectedIds.length === 1 ? shapes.find(s => s.id === selectedIds[0]) : null, [selectedIds, shapes]);

    useEffect(() => {
        if (proxyRef.current && selectionCenter && !draggingRef.current) {
            proxyRef.current.position.copy(selectionCenter);
            if (selectedShape) {
                proxyRef.current.rotation.set(0, selectedShape.rotation, 0);
            } else {
                proxyRef.current.rotation.set(0, 0, 0);
            }
            proxyRef.current.scale.set(1, 1, 1);
        }
    }, [selectionCenter, selectedShape]);

    const handleDragStart = () => {
        if (!selectionCenter) return;
        const map = new Map<string, THREE.Vector3>();
        const movingPoints: { shapeId: string, rel: THREE.Vector3 }[] = [];
        const staticPoints: THREE.Vector3[] = [];
        shapes.forEach(s => {
            if (selectedIds.includes(s.id)) {
                map.set(s.id, new THREE.Vector3(s.position[0], s.position[1], s.position[2]));
                s.points.forEach(p => {
                     const worldP = transformPoint(p, s);
                     movingPoints.push({ shapeId: s.id, rel: worldP.clone().sub(selectionCenter) });
                });
            } else {
                 s.points.forEach(p => { staticPoints.push(transformPoint(p, s)); });
            }
        });
        draggingRef.current = { startPos: selectionCenter.clone(), initialShapePositions: map, movingPoints, staticPoints };
        setSnapGuides([]);
    };

    const handleDrag = () => {
        if (!draggingRef.current || !proxyRef.current) return;
        const currentGizmoPos = proxyRef.current.position.clone();
        const { movingPoints, staticPoints, startPos } = draggingRef.current;
        const rawDelta = currentGizmoPos.clone().sub(startPos);
        let snapAdjustmentX = 0; let snapAdjustmentZ = 0;
        let minDiffX = ALIGN_THRESHOLD; let minDiffZ = ALIGN_THRESHOLD;
        let bestGuideX: THREE.Vector3[] | null = null;
        let bestGuideZ: THREE.Vector3[] | null = null;

        if (movingPoints.length > 0 && staticPoints.length > 0) {
            for (const mp of movingPoints) {
                const candidateX = startPos.x + mp.rel.x + rawDelta.x;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateX - sp.x);
                     if (diff < minDiffX) {
                         minDiffX = diff; snapAdjustmentX = sp.x - candidateX;
                         bestGuideX = [new THREE.Vector3(sp.x, 0.5, -100), new THREE.Vector3(sp.x, 0.5, 100)];
                     }
                }
            }
            for (const mp of movingPoints) {
                const candidateZ = startPos.z + mp.rel.z + rawDelta.z;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateZ - sp.z);
                     if (diff < minDiffZ) {
                         minDiffZ = diff; snapAdjustmentZ = sp.z - candidateZ;
                         bestGuideZ = [new THREE.Vector3(-100, 0.5, sp.z), new THREE.Vector3(100, 0.5, sp.z)];
                     }
                }
            }
        }

        const finalDelta = new THREE.Vector3(rawDelta.x + snapAdjustmentX, rawDelta.y, rawDelta.z + snapAdjustmentZ);
        const newGuides = [];
        if (bestGuideX && Math.abs(snapAdjustmentX) > 0.0001) newGuides.push(bestGuideX);
        if (bestGuideZ && Math.abs(snapAdjustmentZ) > 0.0001) newGuides.push(bestGuideZ);
        setSnapGuides(newGuides);

        scene.children.forEach(child => {
            if (child.userData?.isShape && selectedIds.includes(child.userData.id)) {
                 const initial = draggingRef.current?.initialShapePositions.get(child.userData.id);
                 if (initial) child.position.set(initial.x + finalDelta.x, initial.y + finalDelta.y, initial.z + finalDelta.z);
            }
        });
    };

    const handleDragEnd = () => {
        if (!draggingRef.current || !proxyRef.current) return;
        const currentGizmoPos = proxyRef.current.position;
        const { movingPoints, staticPoints, startPos } = draggingRef.current;
        const rawDelta = currentGizmoPos.clone().sub(startPos);
        let snapAdjustmentX = 0; let snapAdjustmentZ = 0;
        let minDiffX = ALIGN_THRESHOLD; let minDiffZ = ALIGN_THRESHOLD;

        if (movingPoints.length > 0 && staticPoints.length > 0) {
            for (const mp of movingPoints) {
                const candidateX = startPos.x + mp.rel.x + rawDelta.x;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateX - sp.x);
                     if (diff < minDiffX) { minDiffX = diff; snapAdjustmentX = sp.x - candidateX; }
                }
            }
            for (const mp of movingPoints) {
                const candidateZ = startPos.z + mp.rel.z + rawDelta.z;
                for (const sp of staticPoints) {
                     const diff = Math.abs(candidateZ - sp.z);
                     if (diff < minDiffZ) { minDiffZ = diff; snapAdjustmentZ = sp.z - candidateZ; }
                }
            }
        }

        const finalDelta = new THREE.Vector3(rawDelta.x + snapAdjustmentX, rawDelta.y, rawDelta.z + snapAdjustmentZ);
        const updates = selectedIds.map(id => {
            const initial = draggingRef.current?.initialShapePositions.get(id);
            if (!initial) return null;
            return { id, changes: { position: [initial.x + finalDelta.x, initial.y + finalDelta.y, initial.z + finalDelta.z] as [number, number, number] } };
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];

        if (updates.length > 0) updateShapes(updates);
        draggingRef.current = null;
        setSnapGuides([]);
    };

    if (!selectionCenter || tool !== ToolType.SELECT) return null;

    return (
        <>
            <group ref={proxyRef} />
            <TransformControls
                key={selectedIds.join('-')}
                object={proxyRef}
                mode="translate"
                space={selectedShape ? "local" : "world"}
                onMouseDown={handleDragStart}
                onObjectChange={handleDrag}
                onMouseUp={handleDragEnd}
                translationSnap={0.01}
                size={0.8}
            />
            {snapGuides.map((pts, i) => (
                <Line key={`snap-guide-${i}`} points={pts} color="#d946ef" lineWidth={2} dashed dashScale={10} depthTest={false} opacity={0.8} transparent />
            ))}
        </>
    );
};

// --- HOOK: Drawing Logic ---
const useDrawingManager = () => {
    const { tool, addShape, replaceShapes, formatValue, shapes, wallThickness, deselectAll } = useApp();
    const [startPoint, setStartPoint] = useState<IPoint | null>(null);
    const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
    const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);
    const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
    const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);
    const drawSession = useRef<{ active: boolean; startPoint: IPoint; startSnapShapeId: string | null; points: IPoint[]; generatedIds: string[]; }>({ active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] });
    const processingRef = useRef(false);
    const [snapType, setSnapType] = useState<SnapType>('none');
    const [snapObjectId, setSnapObjectId] = useState<string | null>(null);
    const [snapEdge, setSnapEdge] = useState<[THREE.Vector3, THREE.Vector3] | undefined>(undefined);
    const [guides, setGuides] = useState<THREE.Vector3[][]>([]);
    const { raycaster, scene, camera } = useThree();

    useEffect(() => {
        setStartPoint(null); setCurrentPoint(null); setPolyPoints([]); setMeasureStart(null); setMeasureEnd(null);
        setSnapType('none'); setGuides([]); setSnapEdge(undefined); processingRef.current = false;
        drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
    }, [tool]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                if (drawSession.current.active) {
                    drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
                    setStartPoint(null);
                }
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    useFrame(({ pointer }) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
            if (currentPoint) setCurrentPoint(null);
            return;
        }

        raycaster.setFromCamera(pointer, camera);
        // Robust Intersection: Check all objects in scene to handle stacking and occlusion correctly
        const intersects = raycaster.intersectObjects(scene.children, true);
        let intersection: THREE.Intersection | null = null;

        for (const hit of intersects) {
            if (!hit.object.visible) continue;
            // Ground
            if (hit.object.name === 'ground_plane') {
                intersection = hit;
                break;
            }
            // Shape or Dimension?
            let isDimension = false;
            let isShape = false;
            let curr: THREE.Object3D | null = hit.object;
            while (curr) {
                if (curr.name === 'dimension_group') { isDimension = true; break; }
                if (curr.userData?.isShape) { isShape = true; }
                curr = curr.parent;
            }
            if (isDimension) continue; // Ignore dimensions
            if (isShape) {
                intersection = hit;
                break; // Hit a shape
            }
        }

        if (intersection) {
            const rawPoint = intersection.point;
            const activeSnapPoints = [...polyPoints];
            if (startPoint) activeSnapPoints.push(startPoint);
            if (drawSession.current.active && drawSession.current.points.length > 0) activeSnapPoints.push(drawSession.current.points[0]);
            if (measureStart) activeSnapPoints.push(measureStart);

            const snapResult = getGeometrySnap(rawPoint, shapes, activeSnapPoints, SNAP_THRESHOLD, intersection);

            const x = snapResult.position.x;
            const z = snapResult.position.z;
            let y = snapResult.position.y;
            // Only zero-out Y if we snapped to grid (air/ground) AND we are close to 0.
            // If we snapped to face/vertex/edge, preserve height.
            if (snapResult.type === 'grid' && y < 0.05) y = 0;

            if (!currentPoint || Math.abs(currentPoint.x - x) > 0.001 || Math.abs(currentPoint.z - z) > 0.001 || Math.abs(currentPoint.y - y) > 0.001 || snapType !== snapResult.type) {
                setCurrentPoint({ x, y, z });
                setSnapType(snapResult.type);
                setSnapObjectId(snapResult.snapObjectId || null);
                setSnapEdge(snapResult.snapEdge);
                setGuides(snapResult.guides || []);
            }
        } else {
            if (currentPoint) {
                setCurrentPoint(null); setSnapType('none'); setSnapObjectId(null); setSnapEdge(undefined); setGuides([]);
            }
        }
    });

    const createPolygonShapeObject = (pts: IPoint[]): IShape => {
        const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
        const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
        const cy = pts[0].y;
        const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
        centeredPoints.push(centeredPoints[0]); 
        return {
            id: `poly-${Date.now()}`, name: `多邊形`, type: 'flat', points: centeredPoints, height: DEFAULT_HEIGHT, color: FLAT_COLOR,
            position: [cx, cy, cz], rotation: 0, scale: [1, 1, 1]
        };
    };

    const createPolygonShape = (pts: IPoint[]) => {
        const shape = createPolygonShapeObject(pts);
        addShape(shape);
    };

    const finishPrimitive = (start: IPoint, end: IPoint) => {
        if (processingRef.current) return;
        processingRef.current = true;
        let points: IPoint[] = [];
        let name = "平面";
        const cx = (start.x + end.x) / 2;
        const cz = (start.z + end.z) / 2;
        const dx = end.x - start.x;
        const dz = end.z - start.z;
        const dist = Math.sqrt(dx*dx + dz*dz);
        let finalPos: [number, number, number] = [0,0,0];

        switch (tool) {
            case ToolType.DRAW_LINE:
                const thickness = wallThickness; 
                const len = dist;
                points = [{ x: 0, y: 0, z: -thickness/2 }, { x: len, y: 0, z: -thickness/2 }, { x: len, y: 0, z: thickness/2 }, { x: 0, y: 0, z: thickness/2 }, { x: 0, y: 0, z: -thickness/2 }];
                finalPos = [start.x, start.y, start.z]; name = "牆面";
                break;
            case ToolType.DRAW_RECT:
                const w = Math.abs(dx); const d = Math.abs(dz);
                finalPos = [cx, start.y, cz];
                points = [{ x: -w/2, y: 0, z: -d/2 }, { x: w/2, y: 0, z: -d/2 }, { x: w/2, y: 0, z: d/2 }, { x: -w/2, y: 0, z: d/2 }, { x: -w/2, y: 0, z: -d/2 }];
                name = "區域";
                break;
            case ToolType.DRAW_CIRCLE:
                finalPos = [start.x, start.y, start.z]; points = createCirclePoints(dist); name = "圓形";
                break;
            case ToolType.DRAW_ARC:
                finalPos = [start.x, start.y, start.z]; points = createArcPoints(dist); name = "開門";
                break;
        }
        let rotation = 0;
        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) rotation = -Math.atan2(dz, dx); 
        const isSurface = tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_POLY;
        const newShape: IShape = {
            id: `shape-${Date.now()}-${Math.floor(Math.random()*1000)}`, name: isSurface ? "多邊形" : `${name}`, type: isSurface ? 'flat' : 'flat',
            points, height: DEFAULT_HEIGHT, color: isSurface ? FLAT_COLOR : DEFAULT_COLOR, position: finalPos, rotation: rotation, scale: [1, 1, 1]
        };

        if (tool === ToolType.DRAW_LINE && drawSession.current.active) {
            drawSession.current.points.push(end);
            drawSession.current.generatedIds.push(newShape.id);
        }

        const idsToRemove: string[] = [];
        const newShapesToAdd: IShape[] = [newShape];
        let sessionReset = false;

        if (tool === ToolType.DRAW_LINE && drawSession.current.active) {
            const session = drawSession.current;
            const startSnapId = session.startSnapShapeId;
            const endSnapId = snapObjectId;
            if (startSnapId && endSnapId && startSnapId === endSnapId && session.points.length >= 2) {
                const targetShape = shapes.find(s => s.id === startSnapId);
                if (targetShape && targetShape.type !== 'dimension') {
                    const worldShapePoints = targetShape.points.map(p => transformPoint(p, targetShape));
                    const splitResult = splitShapeByPolyline({ ...targetShape, points: worldShapePoints }, session.points);
                    if (splitResult) {
                        idsToRemove.push(targetShape.id); idsToRemove.push(...session.generatedIds);
                        newShapesToAdd.length = 0; newShapesToAdd.push(...splitResult);
                        sessionReset = true;
                    }
                }
            }
        }
        if (idsToRemove.length > 0) replaceShapes(idsToRemove, newShapesToAdd);
        else addShape(newShape);

        if (tool === ToolType.DRAW_LINE && !sessionReset) {
            setStartPoint(end);
        } else {
            setStartPoint(null);
            if (tool === ToolType.DRAW_LINE) drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
        }
        setTimeout(() => { processingRef.current = false; }, 100);
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        // Selection is handled by ShapeRenderer, but if we are in drawing mode, we want to capture clicks anywhere.
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
            if (!e.shiftKey) deselectAll();
            return;
        }
        if (!currentPoint) return;
        // Important: Stop propagation so we don't trigger multiple clicks if bubbles up from shape -> group -> etc
        // But since we attach this to a wrapper group and ground, we just handle it once.
        e.stopPropagation(); 
        if (processingRef.current) return;

        const p = { ...currentPoint };

        if (tool === ToolType.MEASURE) {
            if (!measureStart) {
                setMeasureStart(p); setMeasureEnd(null);
            } else {
                const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2) + Math.pow(p.y - measureStart.y, 2));
                if (dist > 0.01) {
                    addShape({
                        id: `dim-${Date.now()}`, name: '尺寸標註', type: 'dimension', points: [measureStart, p], height: 0,
                        color: DIMENSION_COLOR, position: [0, 0, 0], rotation: 0, scale: [1, 1, 1]
                    });
                }
                setMeasureStart(null); setMeasureEnd(null);
            }
            return;
        }

        if (tool === ToolType.DRAW_POLY) {
            if (polyPoints.length > 2) {
                const start = polyPoints[0];
                const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
                if (dist < SNAP_THRESHOLD) { createPolygonShape(polyPoints); setPolyPoints([]); return; }
            }
            setPolyPoints([...polyPoints, p]);
            return;
        } 

        if (!startPoint) {
            setStartPoint(p);
            if (tool === ToolType.DRAW_LINE) {
                drawSession.current = { active: true, startPoint: p, startSnapShapeId: snapObjectId || null, points: [p], generatedIds: [] };
            }
        } else {
            if (tool === ToolType.DRAW_LINE && drawSession.current.active) {
                const start = drawSession.current.points[0];
                const distToStart = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
                if (distToStart < SNAP_THRESHOLD && drawSession.current.points.length > 2) {
                    const polyPts = [...drawSession.current.points];
                    const newPoly = createPolygonShapeObject(polyPts);
                    replaceShapes(drawSession.current.generatedIds, [newPoly]);
                    drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
                    setStartPoint(null);
                    return;
                }
            }
            const dist = Math.sqrt(Math.pow(p.x - startPoint.x, 2) + Math.pow(p.z - startPoint.z, 2));
            if (dist > 0.01) finishPrimitive(startPoint, p);
        }
    };

    const drawY = useMemo(() => {
        if (startPoint) return startPoint.y;
        if (polyPoints.length > 0) return polyPoints[0].y;
        if (currentPoint) return currentPoint.y;
        return 0;
    }, [startPoint, polyPoints, currentPoint]);

    return {
        startPoint, currentPoint, polyPoints, measureStart, measureEnd,
        snapType, snapEdge, guides, drawY, handleClick
    };
};

const DrawingVisuals: React.FC<ReturnType<typeof useDrawingManager>> = ({ 
    startPoint, currentPoint, polyPoints, measureStart, measureEnd, 
    snapType, snapEdge, guides, drawY, handleClick 
}) => {
    const { tool, formatValue, wallThickness } = useApp();

    // ... (Keep existing previewPoints and getTooltipText logic)
    const previewPoints = useMemo(() => {
        if (tool === ToolType.DRAW_POLY) {
           if (polyPoints.length === 0 && !currentPoint) return [];
           const pts = [...polyPoints];
           if (currentPoint) pts.push(currentPoint);
           return pts;
        }
        if (startPoint && currentPoint) {
            if (tool === ToolType.DRAW_LINE) {
                // ... Line Loop Check ... (Simplified for brevity, logic same as before)
                const thickness = wallThickness; 
                const dx = currentPoint.x - startPoint.x; const dz = currentPoint.z - startPoint.z; const len = Math.sqrt(dx*dx + dz*dz);
                if (len < 0.01) return [startPoint, currentPoint];
                const nx = -dz / len; const nz = dx / len; const ox = nx * (thickness / 2); const oz = nz * (thickness / 2);
                return [{ x: startPoint.x + ox, y: 0, z: startPoint.z + oz }, { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz }, { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz }, { x: startPoint.x - ox, y: 0, z: startPoint.z - oz }, { x: startPoint.x + ox, y: 0, z: startPoint.z + oz }];
            }
            if (tool === ToolType.DRAW_RECT) return [startPoint, { x: currentPoint.x, y: 0, z: startPoint.z }, currentPoint, { x: startPoint.x, y: 0, z: currentPoint.z }, startPoint];
            if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
                const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
                const func = tool === ToolType.DRAW_CIRCLE ? createCirclePoints : createArcPoints;
                const seg = tool === ToolType.DRAW_CIRCLE ? 64 : 32;
                return func(dist, seg).map(p => ({ x: p.x + startPoint.x, y: 0, z: p.z + startPoint.z }));
            }
        }
        return [];
    }, [tool, startPoint, currentPoint, polyPoints, wallThickness]);

    const getTooltipText = () => {
        if (startPoint && currentPoint) {
            const dx = Math.abs(currentPoint.x - startPoint.x);
            const dz = Math.abs(currentPoint.z - startPoint.z);
            const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
            if (tool === ToolType.DRAW_RECT) return `W: ${formatValue(dx)} x D: ${formatValue(dz)}`;
            if (tool === ToolType.DRAW_LINE) return `L: ${formatValue(dist)}`;
            if (tool === ToolType.DRAW_CIRCLE) return `R: ${formatValue(dist)}`;
            if (tool === ToolType.DRAW_ARC) return `R: ${formatValue(dist)}`;
        }
        if (tool === ToolType.MEASURE && measureStart && currentPoint) {
          const dist = Math.sqrt(Math.pow(currentPoint.x - measureStart.x, 2) + Math.pow(currentPoint.z - measureStart.z, 2) + Math.pow(currentPoint.y - measureStart.y, 2));
          return `距離: ${formatValue(dist)}`;
        }
        if (snapType === 'vertex') return "端點";
        if (snapType === 'midpoint') return "中點";
        if (snapType === 'edge') return "在邊線上";
        if (snapType === 'face') return "在表面上";
        if (snapType === 'align') return "對齊";
        return "";
    };

    const tooltipText = getTooltipText();
    const isClosingLoop = tooltipText === "封閉形狀";

    return (
        <>
            <mesh name="ground_plane" rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]} onClick={handleClick}>
                <planeGeometry args={[100, 100]} />
                <meshBasicMaterial color="black" transparent opacity={0} />
            </mesh>
            {currentPoint && tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && (
                <group position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]}>
                    {(snapType === 'grid' || snapType === 'none') && <mesh rotation={[-Math.PI / 2, 0, 0]}><ringGeometry args={[0.1, 0.15, 32]} /><meshBasicMaterial color={isClosingLoop ? "#facc15" : "#ef4444"} depthTest={false} /></mesh>}
                    <SnapIndicator position={new THREE.Vector3(0,0,0)} type={snapType} snapEdge={snapEdge} />
                </group>
            )}
            {guides.map((pts, i) => (<Line key={`guide-${i}`} points={pts.map(p => [p.x, p.y + 0.06, p.z] as [number, number, number])} color="#a855f7" lineWidth={2} dashed dashScale={10} depthTest={false} />))}
            {tool === ToolType.MEASURE && measureStart && (
                <>
                    <group position={[measureStart.x, measureStart.y + 0.05, measureStart.z]}>
                        <mesh rotation={[-Math.PI / 2, 0, 0]}><circleGeometry args={[0.08, 16]} /><meshBasicMaterial color="#facc15" depthTest={false} /></mesh>
                        <mesh rotation={[-Math.PI / 2, 0, 0]}><ringGeometry args={[0.08, 0.12, 16]} /><meshBasicMaterial color="black" transparent opacity={0.5} depthTest={false} /></mesh>
                    </group>
                    <Line points={[[measureStart.x, measureStart.y + 0.05, measureStart.z], (() => { const target = measureEnd || currentPoint || measureStart; return [target.x, target.y + 0.05, target.z] as [number, number, number]; })()]} color="#facc15" lineWidth={3} dashed dashScale={30} depthTest={false} />
                    {(measureEnd || currentPoint) && (<mesh position={(() => { const p = measureEnd || currentPoint; return p ? [p.x, p.y + 0.05, p.z] : [0,0,0]; })()}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="#facc15" depthTest={false} /></mesh>)}
                </>
            )}
            {currentPoint && tooltipText && <CursorTooltip position={[currentPoint.x, currentPoint.y + 0.5, currentPoint.z]} text={tooltipText} type={snapType} />}
            {previewPoints.length > 0 && (startPoint || polyPoints.length > 0 || isClosingLoop) && <PreviewFill points={previewPoints} y={drawY} />}
            {previewPoints.length > 1 && <Line name="preview_helper" points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])} color="#38bdf8" lineWidth={2} transparent opacity={0.8} />}
        </>
    );
};

const ShapeRenderer: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const { unit } = useApp();
    if (shape.type === 'dimension') {
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id }} name="dimension_group">
                <Line points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.5, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg">{labelText}</div>
                </Html>
             </group>
         );
    }
    return (
        <group position={[shape.position[0], shape.position[1], shape.position[2]]} rotation={[0, shape.rotation, 0]} scale={[shape.scale[0], shape.scale[1], shape.scale[2]]} userData={{ isShape: true, id: shape.id }} name="shape_group" onClick={onSelect}>
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
            </mesh>
             <mesh rotation={[-Math.PI/2, 0, 0]} userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshBasicMaterial color="black" wireframe transparent opacity={0.1} />
            </mesh>
        </group>
    );
};

