import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

// --- Geometry Helpers ---
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false;
    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false;
    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false;
    return true;
};

const findEdgeIndex = (poly: IPoint[], p: IPoint): number => {
    for (let i = 0; i < poly.length; i++) {
        const p1 = poly[i];
        const p2 = poly[(i + 1) % poly.length];
        if (isPointOnSegment(p, p1, p2)) return i;
    }
    return -1;
};

const splitShapeByPolyline = (shape: IShape, polyline: IPoint[]): IShape[] | null => {
    const poly = shape.points;
    if (polyline.length < 2) return null;

    const startP = polyline[0];
    const endP = polyline[polyline.length - 1];

    const idxA = findEdgeIndex(poly, startP);
    const idxB = findEdgeIndex(poly, endP);

    if (idxA === -1 || idxB === -1) return null;

    const newPoly1: IPoint[] = [startP];
    for (let i = 1; i < polyline.length; i++) {
        newPoly1.push(polyline[i]);
    }
    let curr = (idxB + 1) % poly.length;
    while (curr !== (idxA + 1) % poly.length) {
        newPoly1.push(poly[curr]);
        curr = (curr + 1) % poly.length;
    }

    const newPoly2: IPoint[] = [endP];
    for (let i = polyline.length - 2; i >= 0; i--) {
        newPoly2.push(polyline[i]);
    }
    curr = (idxA + 1) % poly.length;
    while (curr !== (idxB + 1) % poly.length) {
        newPoly2.push(poly[curr]);
        curr = (curr + 1) % poly.length;
    }

    const makeShape = (pts: IPoint[], suffix: string): IShape => {
        const uniquePts = pts.filter((p, i) => {
             const next = pts[(i+1)%pts.length];
             return Math.abs(p.x - next.x) > EPSILON || Math.abs(p.z - next.z) > EPSILON;
        });
        if (uniquePts.length < 3) return shape; 

        const cx = uniquePts.reduce((s, p) => s + p.x, 0) / uniquePts.length;
        const cz = uniquePts.reduce((s, p) => s + p.z, 0) / uniquePts.length;

        const localPts = uniquePts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
        localPts.push(localPts[0]); 

        return {
            ...shape,
            id: `${shape.id}-${suffix}`,
            position: [cx, shape.position[1], cz],
            points: localPts,
            rotation: 0, 
            scale: [1, 1, 1]
        };
    };

    return [makeShape(newPoly1, 'cut1'), makeShape(newPoly2, 'cut2')];
};

const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;

  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;

  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;

  if (l2 === 0) return v;

  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));

  return new THREE.Vector3(
    v.x + t * vwx,
    v.y + t * vwy,
    v.z + t * vwz
  );
};

// --- Geometry Snapping Logic ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    // 0. Active Points
    if (activePoints && activePoints.length > 0) {
        for (const p of activePoints) {
             const pt = new THREE.Vector3(p.x, p.y, p.z);
             const dist = pt.distanceTo(cursorPos);
             if (dist < threshold && dist < bestSnap.distance) {
                 bestSnap = { position: pt, type: 'vertex', distance: dist };
             }
        }
    }

    // 1. Vertices
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    // 2. Edges & Midpoints
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    // 3. Face
    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    // 4. Align
    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;
    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       s.points.forEach(p => candidates.push(transformPoint(p, s)));
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));
    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) { minDiffX = diffX; alignX = pt.x; guideXSrc = pt; }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) { minDiffZ = diffZ; alignZ = pt.z; guideZSrc = pt; }
    }
    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;
        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        if (alignZ !== null && guideZSrc) guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        return { position: snappedPos, type: 'align', distance: 0, guides };
    }

    return bestSnap;
};

// --- Custom Hooks & Components ---

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, unit } = useApp();
    const { scene } = useThree();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);

    useFrame((state) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        // Raycast logic to update cursor position and snap info
        const raycaster = state.raycaster;
        raycaster.setFromCamera(state.pointer, state.camera);

        const groundNormal = new THREE.Vector3(0, 1, 0);
        const plane = new THREE.Plane(groundNormal, 0);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);

        if (hit) {
            const intersects = raycaster.intersectObjects(scene.children, true);
            const firstObjHit = intersects.find(i => i.object.userData?.isShape);

            const snap = getGeometrySnap(target, shapes, drawPoints, SNAP_THRESHOLD, firstObjHit);

            // Optimization: Only update state if significantly changed to avoid excessive re-renders
            if (snap.position.distanceTo(cursorPos) > 0.001 || snap.type !== snapInfo?.type) {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            }
        }
    });

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        e.stopPropagation();

        const p = { x: cursorPos.x, y: 0, z: cursorPos.z };

        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY) {
            const newPoints = [...drawPoints, p];

            // Check for closing loop for POLY
            if (tool === ToolType.DRAW_POLY && newPoints.length > 2) {
                const first = newPoints[0];
                const dist = Math.sqrt((p.x - first.x)**2 + (p.z - first.z)**2);
                if (dist < SNAP_THRESHOLD) {
                    newPoints.pop(); // Remove closing point
                    if (newPoints.length >= 3) {
                         const center = {
                            x: newPoints.reduce((s, pt) => s + pt.x, 0) / newPoints.length,
                            z: newPoints.reduce((s, pt) => s + pt.z, 0) / newPoints.length,
                         };
                         const localPoints = newPoints.map(pt => ({ x: pt.x - center.x, y: 0, z: pt.z - center.z }));
                         addShape({
                            id: `poly-${Date.now()}`,
                            type: 'solid',
                            name: 'Polygon',
                            points: localPoints,
                            height: 1.0,
                            color: DEFAULT_COLOR,
                            position: [center.x, 0, center.z],
                            rotation: 0,
                            scale: [1, 1, 1]
                        });
                        setDrawPoints([]);
                        return;
                    }
                }
            }

            // Wall creation for DRAW_LINE
            if (tool === ToolType.DRAW_LINE && drawPoints.length === 1) {
                const start = drawPoints[0];
                const end = p;

                const dx = end.x - start.x;
                const dz = end.z - start.z;
                const length = Math.sqrt(dx*dx + dz*dz);
                if (length < 0.01) return;

                const angle = Math.atan2(dz, dx);

                const cx = (start.x + end.x) / 2;
                const cz = (start.z + end.z) / 2;

                const halfL = length / 2;
                const halfT = wallThickness / 2;

                const points = [
                    { x: -halfL, y: 0, z: -halfT },
                    { x: halfL, y: 0, z: -halfT },
                    { x: halfL, y: 0, z: halfT },
                    { x: -halfL, y: 0, z: halfT }
                ];

                addShape({
                    id: `wall-${Date.now()}`,
                    type: 'solid',
                    name: 'Wall',
                    points: points,
                    height: 3.0,
                    color: DEFAULT_COLOR,
                    position: [cx, 0, cz],
                    rotation: -angle,
                    scale: [1, 1, 1]
                });

                // Continue drawing from the end point
                setDrawPoints([p]);
                return;
            } else if (tool === ToolType.DRAW_LINE && drawPoints.length === 0) {
                 setDrawPoints([p]);
                 return;
            }

            setDrawPoints(newPoints);
        } else if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
            if (drawPoints.length === 0) {
                setDrawPoints([p]);
            } else {
                const start = drawPoints[0];
                const end = p;

                if (tool === ToolType.DRAW_RECT) {
                    const width = Math.abs(end.x - start.x);
                    const depth = Math.abs(end.z - start.z);
                    if (width < 0.01 || depth < 0.01) return;

                    const cx = (start.x + end.x) / 2;
                    const cz = (start.z + end.z) / 2;

                    const points = [
                        { x: -width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: depth/2 },
                    ];

                    addShape({
                        id: `rect-${Date.now()}`,
                        type: 'flat',
                        name: 'Area',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [cx, 0, cz],
                        rotation: 0,
                        scale: [1, 1, 1]
                    });
                } else if (tool === ToolType.DRAW_CIRCLE) {
                    const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                    if (radius < 0.01) return;
                    const points = createCirclePoints(radius);
                    addShape({
                        id: `circle-${Date.now()}`,
                        type: 'flat',
                        name: 'Circle',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [start.x, 0, start.z],
                        rotation: 0,
                        scale: [1, 1, 1]
                    });
                } else if (tool === ToolType.DRAW_ARC) {
                     const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                     if (radius < 0.01) return;
                     const points = createArcPoints(radius);
                     const angle = Math.atan2(end.z - start.z, end.x - start.x);

                     addShape({
                        id: `arc-${Date.now()}`,
                        type: 'flat',
                        name: 'Door Swing',
                        points,
                        height: DEFAULT_HEIGHT,
                        color: FLAT_COLOR,
                        position: [start.x, 0, start.z],
                        rotation: -angle, 
                        scale: [1, 1, 1]
                    });
                }

                setDrawPoints([]);
            }
        } else if (tool === ToolType.MEASURE) {
             if (drawPoints.length === 0) {
                 setDrawPoints([p]);
             } else {
                 const start = drawPoints[0];
                 const end = p;
                 addShape({
                    id: `dim-${Date.now()}`,
                    type: 'dimension',
                    name: 'Dimension',
                    points: [start, end],
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                 });
                 setDrawPoints([]);
             }
        }
    };

    return {
        handleClick,
        drawPoints,
        cursorPos,
        snapInfo,
        tool
    };
};

const DrawingVisuals: React.FC<{ drawPoints: IPoint[], cursorPos: THREE.Vector3, snapInfo: SnapResult | null, tool: ToolType }> = ({ drawPoints, cursorPos, snapInfo, tool }) => {
    const { formatValue } = useApp();

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    const points = drawPoints.map(p => new THREE.Vector3(p.x, p.y + 0.05, p.z));
    const cursor = new THREE.Vector3(cursorPos.x, cursorPos.y + 0.05, cursorPos.z);

    let previewShape: JSX.Element | null = null;
    let infoText = "";

    if (drawPoints.length > 0) {
        const start = points[0];

        if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_POLY || tool === ToolType.MEASURE) {
            const last = points[points.length - 1];
            const dist = last.distanceTo(cursor);
            infoText = `L: ${formatValue(dist)}`;
            previewShape = <Line points={[...points, cursor]} color={tool === ToolType.MEASURE ? DIMENSION_COLOR : "black"} lineWidth={2} dashed={tool === ToolType.MEASURE} dashScale={10} />;
        } else if (tool === ToolType.DRAW_RECT) {
             const width = Math.abs(cursor.x - start.x);
             const depth = Math.abs(cursor.z - start.z);
             infoText = `W: ${formatValue(width)} D: ${formatValue(depth)}`;

             const p1 = start;
             const p2 = new THREE.Vector3(cursor.x, start.y, start.z);
             const p3 = cursor;
             const p4 = new THREE.Vector3(start.x, start.y, cursor.z);

             previewShape = <Line points={[p1, p2, p3, p4, p1]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(cursor);
             infoText = `R: ${formatValue(radius)}`;

             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <Line points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(cursor);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <Line points={[start, cursor]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else {
                 infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
             }
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}

            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}

            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip 
                    text={infoText || snapInfo!.type} 
                    position={cursorPos} 
                    type={snapInfo?.type} 
                 />
            )}

            {snapInfo?.guides?.map((guide, i) => (
                <Line key={i} points={guide} color="#a855f7" lineWidth={1} dashed dashScale={5} />
            ))}
        </group>
    );
};

const SelectionGizmo: React.FC = () => {
    const { selectedIds, updateShape, transformMode, shapes } = useApp();
    const { scene } = useThree();
    const [target, setTarget] = useState<THREE.Object3D | null>(null);

    useEffect(() => {
        if (selectedIds.length === 1) {
            let found: THREE.Object3D | undefined;
            scene.traverse((child) => {
                if (child.userData?.id === selectedIds[0] && child.name === 'shape_group') {
                    found = child;
                }
            });
            setTarget(found || null);
        } else {
            setTarget(null);
        }
    }, [selectedIds, scene, shapes.length]);

    if (!target) return null;

    return (
        <TransformControls
            object={target}
            mode={transformMode}
            translationSnap={0.1}
            rotationSnap={Math.PI / 12}
            scaleSnap={0.1}
            showY={transformMode === 'translate' ? false : true}
            onMouseUp={() => {
                if (target) {
                    updateShape(selectedIds[0], {
                        position: [target.position.x, target.position.y, target.position.z],
                        rotation: target.rotation.y,
                        scale: [target.scale.x, target.scale.y, target.scale.z]
                    });
                }
            }}
        />
    );
};

// --- Components ---
const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        const ctrl = controls as unknown as OrbitControlsImpl;
        if (!ctrl) return;
        const currentTarget = ctrl.target.clone();
        const dist = camera.position.distanceTo(currentTarget) || 10;
        const offset = 0.001; 
        switch (view) {
            case '上視圖': camera.position.set(currentTarget.x, currentTarget.y + dist, currentTarget.z + offset); break;
            case '下視圖': camera.position.set(currentTarget.x, currentTarget.y - dist, currentTarget.z + offset); break;
            case '前視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z + dist); break;
            case '後視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z - dist); break;
            case '右視圖': camera.position.set(currentTarget.x + dist, currentTarget.y, currentTarget.z); break;
            case '左視圖': camera.position.set(currentTarget.x - dist, currentTarget.y, currentTarget.z); break;
        }
        ctrl.update();
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number]; type?: SnapType }> = ({ text, position, type }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
  let bgColor = "bg-black/80";
  let ringColor = "border-white/20";
  let textColor = "text-white";
  if (type === 'vertex') { bgColor = "bg-green-600"; ringColor = "border-green-400"; }
  else if (type === 'midpoint') { bgColor = "bg-cyan-500"; ringColor = "border-cyan-300"; textColor="text-black"; }
  else if (type === 'edge') { bgColor = "bg-red-600"; ringColor = "border-red-400"; }
  else if (type === 'face') { bgColor = "bg-blue-600"; ringColor = "border-blue-400"; }
  else if (type === 'align') { bgColor = "bg-purple-600"; ringColor = "border-purple-400"; }
  if (text.includes('W:') || text.includes('L:') || text.includes('R:') || text.includes('距離:')) {
      bgColor = "bg-slate-800";
      ringColor = "border-slate-500";
      textColor = "text-yellow-400 font-mono";
  }
  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
      <div className={`${bgColor} ${textColor} text-xs px-2 py-1 rounded-sm whitespace-nowrap backdrop-blur-sm border ${ringColor} shadow-[0_2px_4px_rgba(0,0,0,0.3)] font-bold flex items-center gap-1 transition-all -translate-y-8`}>
        {text}
      </div>
    </Html>
  );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'none' || type === 'grid') return null;
    const color = type === 'vertex' ? '#22c55e' : type === 'midpoint' ? '#06b6d4' : type === 'edge' ? '#ef4444' : type === 'face' ? '#3b82f6' : '#a855f7';
    return (
        <group>
             <group position={position}>
                {type === 'vertex' && <mesh rotation={[-Math.PI/2, 0, 0]}><circleGeometry args={[0.08, 16]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'midpoint' && <mesh rotation={[-Math.PI/2, 0, 0]}><circleGeometry args={[0.08, 16]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'edge' && <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.12, 0.12]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'face' && <mesh rotation={[-Math.PI/2, 0, Math.PI/4]}><planeGeometry args={[0.1, 0.1]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type === 'align' && <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[0.06, 0.1, 16]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>}
                {type !== 'align' && <mesh rotation={[-Math.PI/2, 0, 0]}><ringGeometry args={[0.12, 0.14, 32]} /><meshBasicMaterial color="white" transparent opacity={0.5} depthTest={false} /></mesh>}
            </group>
            {snapEdge && (type === 'edge' || type === 'midpoint') && (
                <Line points={[snapEdge[0], snapEdge[1]]} color={color} lineWidth={3} depthTest={false} transparent opacity={0.8} />
            )}
        </group>
    );
}

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z);
      for (let i = 1; i < points.length; i++) {
        if (points[i]) s.lineTo(points[i].x, -points[i].z);
      }
    }
    s.closePath();
    return s;
  }, [points]);
  if (!shape) return null;
  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity?: number }> = ({ shape, color, opacity = 0.5 }) => {
    const outlines = useMemo(() => {
        const points = shape.points;
        const h = shape.height;
        const topLoop: [number, number, number][] = [];
        const bottomLoop: [number, number, number][] = [];
        const verticals: [number, number, number][][] = [];

        const len = points.length;
        if (len < 2) return null;

        for (let i = 0; i < len; i++) {
            const curr = points[i];
            const next = points[(i + 1) % len];
            const prev = points[(i - 1 + len) % len];

            // Calculate angle between edges to determine if we need a vertical line
            const v1 = new THREE.Vector2(curr.x - prev.x, (-curr.z) - (-prev.z)).normalize();
            const v2 = new THREE.Vector2(next.x - curr.x, (-next.z) - (-curr.z)).normalize();
            const dot = v1.dot(v2);

            const x = curr.x;
            const y = -curr.z;

            topLoop.push([x, y, h]);
            bottomLoop.push([x, y, 0]);

            // Only draw vertical line if the corner is sharp (angle > ~25 degrees)
            // This prevents smooth cylinders from having a "cage" look, and hides split-lines on flat faces.
            if (dot < 0.9) {
                verticals.push([[x, y, 0], [x, y, h]]);
            }
        }

        if (topLoop.length > 0) topLoop.push(topLoop[0]);
        if (bottomLoop.length > 0) bottomLoop.push(bottomLoop[0]);

        return { topLoop, bottomLoop, verticals };
    }, [shape]);

    if (!outlines) return null;

    return (
        <group rotation={[-Math.PI / 2, 0, 0]}>
             <Line points={outlines.topLoop} color={color} lineWidth={2} transparent opacity={opacity} depthTest={true} />
             <Line points={outlines.bottomLoop} color={color} lineWidth={2} transparent opacity={opacity * 0.5} depthTest={true} />
             {outlines.verticals.map((pts, i) => (
                 <Line key={i} points={pts} color={color} lineWidth={2} transparent opacity={opacity} depthTest={true} />
             ))}
        </group>
    );
};

const ShapeRenderer: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const { unit } = useApp();
    if (shape.type === 'dimension') {
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id }} name="dimension_group">
                <Line points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.5, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg">{labelText}</div>
                </Html>
             </group>
         );
    }
    return (
        <group position={[shape.position[0], shape.position[1], shape.position[2]]} rotation={[0, shape.rotation, 0]} scale={[shape.scale[0], shape.scale[1], shape.scale[2]]} userData={{ isShape: true, id: shape.id }} name="shape_group" onClick={onSelect}>
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
            </mesh>
            <ShapeOutline shape={shape} color="#333" />
        </group>
    );
};

